struct Point { x: u64, y: u64 }
impl Point { fn total(&self) -> u64 { self.x + self.y } }
fn main() { let point = Point { x: 19, y: 23 }; let result = point.total(); println!("{result}"); }

mod math { pub fn twice(value: u64) -> u64 { value * 2 } }
use math::twice;
fn main() { let result = twice(21); println!("{result}"); }

