enum Mode { Fast, Slow }
fn select(mode: Mode) -> u64 { if let Mode::Fast = mode { 42 } else { 0 } }
fn main() { let result = select(Mode::Fast); println!("{result}"); }

macro_rules! identity { ($value:expr) => { $value }; }
pub async fn references<'a, T: Sync + 'a>(values: impl IntoIterator<Item = &'a T>) -> impl Iterator<Item = &'a T> { values.into_iter() }
pub const fn answer() -> usize { identity!(42) }

#[derive(Clone, Debug, PartialEq, Eq)]
struct Marker { value: u64 }
fn main() { let first = Marker { value: 42 }; let second = first.clone(); if first == second { println!("same"); } else { println!("different"); } }

trait Value { fn value(&self) -> u64; }
struct Number;
impl Value for Number { fn value(&self) -> u64 { 42 } }
fn read<T: Value>(item: &T) -> u64 { item.value() }
fn main() { let result = read(&Number); println!("{result}"); }

